/* ── device_control (variable, ≤ 30 B on the wire) ── */

#define BRIDGE_DEVICE_CONTROL_MAX_SIZE 30u

typedef struct {
    uint8_t ver;
    uint8_t op;
    uint8_t body[28]; /* op-specific payload; layouts below */
    uint8_t body_len; /* elements actually present */
} bridge_device_control_t;

/* Serializes *v; returns the wire length, or -1 if a length field
 * exceeds its max or cap is too small. */
static inline int bridge_device_control_pack(const bridge_device_control_t *v, uint8_t *out, size_t cap) {
    if (v->body_len > 28) {
        return -1;
    }
    size_t off = 0;
    size_t need = 0;
    need = 2u + (size_t)v->body_len * 1u;
    if (cap < need) {
        return -1;
    }
    out[off++] = (uint8_t)v->ver;
    out[off++] = (uint8_t)v->op;
    memcpy(out + off, v->body, v->body_len);
    off += v->body_len;
    return (int)off;
}

/* Parses len wire bytes into *v; returns bytes consumed or -1 on
 * truncation / out-of-range lengths. */
static inline int bridge_device_control_unpack(const uint8_t *buf, size_t len, bridge_device_control_t *v) {
    size_t off = 0;
    if (len < off + 1u) {
        return -1;
    }
    v->ver = buf[off++];
    if (len < off + 1u) {
        return -1;
    }
    v->op = buf[off++];
    if (len - off > 28) {
        return -1;
    }
    v->body_len = (uint8_t)(len - off);
    memcpy(v->body, buf + off, (len - off));
    off += (len - off);
    return (int)off;
}

